begin;
create extension if not exists pgtap with schema extensions;
select plan(48);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000080','chat-owner@test.invalid'),('10000000-0000-4000-8000-000000000081','chat-reader@test.invalid'),('10000000-0000-4000-8000-000000000082','chat-outsider@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000080','Chat test'),('20000000-0000-4000-8000-000000000081','Other chat workspace');
insert into public.workspace_members(workspace_id,user_id,role) values ('20000000-0000-4000-8000-000000000080','10000000-0000-4000-8000-000000000080','owner'),('20000000-0000-4000-8000-000000000080','10000000-0000-4000-8000-000000000081','member');
select set_config('test.request','{"template":"product_delivery","version":1,"objective":"Release","context":"Small team","hardConstraints":[{"kind":"prohibition","text":"No downtime"}],"conceptIds":[],"unknowns":""}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000080","role":"authenticated"}',true);
select is(public.create_conversation('20000000-0000-4000-8000-000000000080','30000000-0000-4000-8000-000000000080'),'30000000-0000-4000-8000-000000000080'::uuid,'conversation created');
select is(public.create_conversation('20000000-0000-4000-8000-000000000080','30000000-0000-4000-8000-000000000080'),'30000000-0000-4000-8000-000000000080'::uuid,'conversation create idempotent');
select throws_ok($$select public.create_conversation('20000000-0000-4000-8000-000000000081',gen_random_uuid())$$,'42501',null,'forged workspace denied');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'Question','{}')$$,'23514',null,'direct RPC invalid snapshot rejected');
select set_config('test.turn',public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000080','How can we release?',current_setting('test.request')::jsonb)::text,true);
select is((select count(*) from public.conversation_turns),1::bigint,'turn persisted without model or run');
select is((select count(*) from public.analysis_runs where conversation_turn_id=current_setting('test.turn')::uuid),0::bigint,'saved turn does not claim generation started');
select is(public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000080','How can we release?',current_setting('test.request')::jsonb),current_setting('test.turn')::uuid,'replayed turn returns original');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000080','Different question',current_setting('test.request')::jsonb)$$,'23505',null,'key cannot overwrite a turn');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'Stale question',current_setting('test.request')::jsonb)$$,'23505',null,'stale parent denied');
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,'50000000-0000-4000-8000-000000000080',2,90000)->>'kind','admitted','turn admits through shared engine policy');
select is((select request->>'version' from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000080'),'2','legacy turn admits a text run');
select is((select request->>'message' from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000080'),'How can we release?','text run keeps the original turn message');
select is((select string_agg(item->>'text','' order by ord) from public.analysis_runs r cross join lateral jsonb_array_elements(r.request->'history') with ordinality as h(item,ord) where r.request_key='50000000-0000-4000-8000-000000000080'),'Legacy user-confirmed request snapshot. Concatenate these history messages to read the complete JSON: ' || current_setting('test.request')::jsonb::text,'text run keeps the complete user-confirmed snapshot');
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,'50000000-0000-4000-8000-000000000080',2,90000)->>'kind','duplicate','attempt replay does not create another run');
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,gen_random_uuid(),2,90000)->>'kind','quota','one active run per conversation');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'During run',current_setting('test.request')::jsonb,current_setting('test.turn')::uuid)$$,'23505',null,'cannot append during active run');
select public.finish_analysis((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000080'),'failed',null,'[]','MODEL_UNAVAILABLE',null);
select is(public.admit_conversation_analysis(current_setting('test.turn')::uuid,'50000000-0000-4000-8000-000000000081',2,90000)->>'kind','admitted','terminal failure can retry as a new attempt');
select is((select request from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000081'),(select request from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000080'),'retry preserves the exact converted input');
select public.finish_analysis((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000081'),'complete','{"version":2,"text":"A general answer.","citations":[]}','[]',null,null);
select is((select generated->>'text' from public.briefs where run_id=(select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000081')),'A general answer.','legacy retry can save a versioned text answer');
select throws_ok($$select public.admit_analysis('20000000-0000-4000-8000-000000000080',jsonb_build_object('version',1,'template','product_delivery','objective','Release','context','Team','hardConstraints',(select jsonb_agg(jsonb_build_object('kind','requirement','text',repeat('x',4000))) from generate_series(1,7)),'conceptIds','[]'::jsonb,'unknowns',''),gen_random_uuid(),2,90000)$$,'22023','Conversation context exceeds the limit','oversized legacy snapshot is rejected instead of truncated');
select throws_ok($$select public.admit_conversation_analysis(current_setting('test.turn')::uuid,gen_random_uuid(),2,90000)$$,'23505',null,'answered turn cannot be rerun');
select set_config('test.next',public.save_conversation_turn('30000000-0000-4000-8000-000000000080','40000000-0000-4000-8000-000000000081','What if only one operator?',jsonb_set(current_setting('test.request')::jsonb,'{context}',to_jsonb(E'Small team\n\nFollow-up from user: What if only one operator?'::text)),current_setting('test.turn')::uuid)::text,true);
select is((select position from public.conversation_turns where id=current_setting('test.next')::uuid),2,'follow-up keeps ordered history');
select throws_ok($$select public.admit_conversation_analysis(current_setting('test.turn')::uuid,gen_random_uuid(),2,90000)$$,'23505',null,'cannot run an older turn after follow-up');
select is(public.admit_conversation_analysis(current_setting('test.next')::uuid,'50000000-0000-4000-8000-000000000082',2,90000)->>'kind','admitted','legacy follow-up admits through the text path');
select is((select request->'history'->0->>'text' from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000082'),'The user message was appended as the final follow-up in legacy context. Concatenate these history messages to read the remaining user-confirmed request JSON: '||current_setting('test.request')::jsonb::text,'follow-up appears once and the original context remains reconstructable');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000081","role":"authenticated"}',true);
select is((select count(*) from public.conversation_turns),2::bigint,'workspace member can read history');
select throws_ok($$select public.save_conversation_turn('30000000-0000-4000-8000-000000000080',gen_random_uuid(),'Another author',current_setting('test.request')::jsonb,current_setting('test.next')::uuid)$$,'42501',null,'another member cannot append');
select throws_ok($$select public.admit_conversation_analysis(current_setting('test.next')::uuid,gen_random_uuid(),2,90000)$$,'42501',null,'another member cannot execute');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000082","role":"authenticated"}',true);
select is((select count(*) from public.conversations),0::bigint,'nonmember cannot read conversations');
select is((select count(*) from public.conversation_turns),0::bigint,'nonmember cannot read snapshots');
-- Deleting a conversation: author only, never while a run is live, and no direct delete.
select throws_ok($$select public.delete_conversation('30000000-0000-4000-8000-000000000080')$$,'42501',null,'another member cannot delete');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000082","role":"authenticated"}',true);
select throws_ok($$select public.delete_conversation('30000000-0000-4000-8000-000000000080')$$,'42501',null,'nonmember cannot delete');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000080","role":"authenticated"}',true);
select throws_ok($$select public.delete_conversation('30000000-0000-4000-8000-000000000999')$$,'42501',null,'unknown conversation is unavailable');
select throws_ok($$select public.delete_conversation('30000000-0000-4000-8000-000000000080')$$,'23505',null,'author cannot delete while a run is live');
select throws_ok($$delete from public.conversation_turns$$,'42501',null,'no direct delete of turns');
select throws_ok($$delete from public.conversations$$,'42501',null,'no direct delete of conversations');
select public.create_conversation('20000000-0000-4000-8000-000000000080','30000000-0000-4000-8000-000000000081');
select set_config('test.turn2',public.save_conversation_turn('30000000-0000-4000-8000-000000000081','40000000-0000-4000-8000-000000000090','Second question',current_setting('test.request')::jsonb)::text,true);
select public.admit_conversation_analysis(current_setting('test.turn2')::uuid,'50000000-0000-4000-8000-000000000090',2,90000);
select public.finish_analysis((select id from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000090'),'complete','{"version":2,"text":"Answer.","citations":[]}','[]',null,null);
select lives_ok($$select public.delete_conversation('30000000-0000-4000-8000-000000000081')$$,'author deletes a finished conversation');
select is((select count(*) from public.conversations where id='30000000-0000-4000-8000-000000000081'),0::bigint,'conversation removed');
select is((select count(*) from public.conversation_turns where conversation_id='30000000-0000-4000-8000-000000000081'),0::bigint,'turns removed');
select is((select count(*) from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000090'),0::bigint,'runs removed');
select is((select count(*) from public.briefs where generated->>'text'='Answer.'),0::bigint,'briefs removed');
select is((select count(*) from public.conversation_turns where conversation_id='30000000-0000-4000-8000-000000000080'),2::bigint,'other conversations keep their turns');
select public.create_conversation('20000000-0000-4000-8000-000000000080','30000000-0000-4000-8000-000000000082');
select set_config('test.turn3',public.save_conversation_turn('30000000-0000-4000-8000-000000000082','40000000-0000-4000-8000-000000000091','Third question',current_setting('test.request')::jsonb)::text,true);
select public.admit_conversation_analysis(current_setting('test.turn3')::uuid,'50000000-0000-4000-8000-000000000091',2,90000);
reset role;
update public.analysis_runs set deadline_at=now()-interval '1 second' where request_key='50000000-0000-4000-8000-000000000091';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000080","role":"authenticated"}',true);
select lives_ok($$select public.delete_conversation('30000000-0000-4000-8000-000000000082')$$,'an expired run no longer blocks the delete');
select is((select count(*) from public.analysis_runs where request_key='50000000-0000-4000-8000-000000000091'),0::bigint,'expired run removed');
reset role;
select throws_ok($$update public.conversation_turns set message='Overwrite' where id=current_setting('test.turn')::uuid$$,'23514',null,'turns immutable even through privileged writes');
select throws_ok($$insert into public.analysis_runs(workspace_id,author_id,request_key,request,knowledge_version,deadline_at,conversation_turn_id) values('20000000-0000-4000-8000-000000000081','10000000-0000-4000-8000-000000000080',gen_random_uuid(),current_setting('test.request')::jsonb,0,now()+interval '1 minute',current_setting('test.turn')::uuid)$$,'23503',null,'run cannot link a turn across workspaces');
select throws_ok($$delete from public.conversation_turns where id=current_setting('test.turn')::uuid$$,'23514',null,'privileged delete without the setting stays blocked');
select set_config('memoba.deleting_conversation','30000000-0000-4000-8000-000000000999',true);
select throws_ok($$delete from public.conversation_turns where id=current_setting('test.turn')::uuid$$,'23514',null,'the setting for another conversation opens nothing');
select * from finish();
rollback;
